const signal = AbortSignal.timeout(budgetMs);
const settled = await Promise.allSettled(recipients.map(r => fetch(r, { signal })));
const offers = settled.filter(s => s.status === "fulfilled").map(s => parse(s.value));
const partial = settled.length - offers.length;      // make the partial result explicit
return pickBest(offers, partial);

