let left = recipients.length, fired = false, out = new Array(recipients.length);
const finish = () => {
  if (fired) return;
  fired = true; clearTimeout(timer);
  const offers = out.filter(Boolean);
  offers.length ? merge(offers) : fail(new Error("no recipient answered"));
};
const timer = setTimeout(finish, budgetMs);
recipients.forEach((r, i) => ask(r, (err, offer) => { if (!err) out[i] = offer; if (--left === 0) finish(); }));
